package org.debatespeak.authify.dto;
import com.fasterxml.jackson.annotation.JsonProperty;
import java.time.Instant;
import java.util.*;
public final class RoomResponses { private RoomResponses(){} public record Topic(String id,String motion,String category,@JsonProperty("cefr_level") String cefrLevel){} public record Topics(List<Topic> topics){} public record Participant(@JsonProperty("user_id") UUID userId,@JsonProperty("display_name") String displayName,String side,@JsonProperty("is_creator") boolean creator,boolean ready,String input){} public record Snapshot(UUID id,String code,String status,String motion,String format,@JsonProperty("duration_seconds") int durationSeconds,@JsonProperty("expires_at") Instant expiresAt,@JsonProperty("started_at") Instant startedAt,@JsonProperty("ended_at") Instant endedAt,@JsonProperty("end_reason") String endReason,@JsonProperty("ended_by") UUID endedBy,@JsonProperty("server_now") Instant serverNow,List<Participant> participants){} public record Preview(@JsonProperty("room_id") UUID roomId,String motion,@JsonProperty("creator_name") String creatorName,String format,@JsonProperty("duration_seconds") int durationSeconds,@JsonProperty("stance_mode") String stanceMode){} public record Turn(long seq,@JsonProperty("user_id") UUID userId,String text,@JsonProperty("at_ms") long atMs){} public record Turns(List<Turn> turns){} public record LiveKit(String token,String url){} }
